-- Baseline migration for the ASURANSI INTELIGEN OS schema.
-- Applied initially to Neon branch br-crimson-haze-aoajbbfh; use migrations in order on new environments.
CREATE SCHEMA IF NOT EXISTS asuransi;
CREATE TABLE IF NOT EXISTS asuransi.tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asuransi.users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES asuransi.tenants(id), email text NOT NULL, full_name text NOT NULL, password_hash text, status text NOT NULL DEFAULT 'invited' CHECK(status IN ('invited','active','locked','disabled')), mfa_enabled boolean NOT NULL DEFAULT false, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS asuransi.roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES asuransi.tenants(id), code text NOT NULL, name text NOT NULL, permissions jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS asuransi.user_roles (user_id uuid NOT NULL REFERENCES asuransi.users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES asuransi.roles(id) ON DELETE CASCADE, assigned_by uuid REFERENCES asuransi.users(id), assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS asuransi.audit_logs (id bigserial PRIMARY KEY, tenant_id uuid REFERENCES asuransi.tenants(id), actor_user_id uuid REFERENCES asuransi.users(id), action text NOT NULL, resource_type text NOT NULL, resource_id text, request_id text, ip_hash text, user_agent text, outcome text NOT NULL DEFAULT 'success', metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asuransi.clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), client_code text NOT NULL, client_type text NOT NULL DEFAULT 'individual' CHECK(client_type IN ('individual','company')), full_name text NOT NULL, legal_name text, email text, phone text, identity_ref_encrypted text, address jsonb NOT NULL DEFAULT '{}'::jsonb, consent_status text NOT NULL DEFAULT 'pending', source text, owner_user_id uuid REFERENCES asuransi.users(id), status text NOT NULL DEFAULT 'prospect', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, UNIQUE(tenant_id,client_code));
CREATE TABLE IF NOT EXISTS asuransi.leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), lead_code text NOT NULL, client_id uuid REFERENCES asuransi.clients(id), title text NOT NULL, product_interest text, stage text NOT NULL DEFAULT 'new', estimated_premium numeric(18,2) NOT NULL DEFAULT 0 CHECK(estimated_premium>=0), probability numeric(5,2) NOT NULL DEFAULT 0 CHECK(probability BETWEEN 0 AND 100), owner_user_id uuid REFERENCES asuransi.users(id), next_follow_up timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,lead_code));
CREATE TABLE IF NOT EXISTS asuransi.insurers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), code text NOT NULL, name text NOT NULL, license_ref text, contact jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS asuransi.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), insurer_id uuid REFERENCES asuransi.insurers(id), code text NOT NULL, name text NOT NULL, line_of_business text NOT NULL, policy_wording_version text, effective_from date, effective_to date, currency char(3) NOT NULL DEFAULT 'IDR', status text NOT NULL DEFAULT 'draft', rules jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS asuransi.policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), policy_no text NOT NULL, client_id uuid NOT NULL REFERENCES asuransi.clients(id), product_id uuid REFERENCES asuransi.products(id), insurer_id uuid REFERENCES asuransi.insurers(id), status text NOT NULL DEFAULT 'draft', start_date date, end_date date, premium numeric(18,2) NOT NULL DEFAULT 0 CHECK(premium>=0), sum_insured numeric(18,2) NOT NULL DEFAULT 0 CHECK(sum_insured>=0), currency char(3) NOT NULL DEFAULT 'IDR', terms jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, UNIQUE(tenant_id,policy_no));
CREATE TABLE IF NOT EXISTS asuransi.claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), claim_no text NOT NULL, policy_id uuid NOT NULL REFERENCES asuransi.policies(id), claimant_client_id uuid NOT NULL REFERENCES asuransi.clients(id), incident_at timestamptz, reported_at timestamptz NOT NULL DEFAULT now(), claim_type text NOT NULL, description text NOT NULL, claimed_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK(claimed_amount>=0), approved_amount numeric(18,2) CHECK(approved_amount>=0), currency char(3) NOT NULL DEFAULT 'IDR', status text NOT NULL DEFAULT 'submitted', risk_flags jsonb NOT NULL DEFAULT '[]'::jsonb, human_review_required boolean NOT NULL DEFAULT true, decision_reason text, assigned_user_id uuid REFERENCES asuransi.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, UNIQUE(tenant_id,claim_no));
CREATE TABLE IF NOT EXISTS asuransi.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), entity_type text NOT NULL, entity_id uuid NOT NULL, file_name text NOT NULL, media_type text, storage_key text NOT NULL, sha256 text, classification text NOT NULL DEFAULT 'confidential', uploaded_by uuid REFERENCES asuransi.users(id), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS asuransi.employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), employee_no text NOT NULL, full_name text NOT NULL, email text, department text, position text, employment_status text NOT NULL DEFAULT 'active', join_date date, base_salary numeric(18,2) NOT NULL DEFAULT 0 CHECK(base_salary>=0), bank_account_ref_encrypted text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,employee_no));
CREATE TABLE IF NOT EXISTS asuransi.payroll_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), period_start date NOT NULL, period_end date NOT NULL, status text NOT NULL DEFAULT 'draft', total_gross numeric(18,2) NOT NULL DEFAULT 0, total_deductions numeric(18,2) NOT NULL DEFAULT 0, total_net numeric(18,2) NOT NULL DEFAULT 0, approved_by uuid REFERENCES asuransi.users(id), approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,period_start,period_end));
CREATE TABLE IF NOT EXISTS asuransi.payroll_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payroll_run_id uuid NOT NULL REFERENCES asuransi.payroll_runs(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES asuransi.employees(id), gross numeric(18,2) NOT NULL DEFAULT 0, deductions numeric(18,2) NOT NULL DEFAULT 0, net numeric(18,2) NOT NULL DEFAULT 0, components jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE(payroll_run_id,employee_id));
CREATE TABLE IF NOT EXISTS asuransi.chart_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), account_code text NOT NULL, account_name text NOT NULL, account_type text NOT NULL CHECK(account_type IN ('asset','liability','equity','revenue','expense')), parent_id uuid REFERENCES asuransi.chart_accounts(id), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,account_code));
CREATE TABLE IF NOT EXISTS asuransi.journal_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), journal_no text NOT NULL, entry_date date NOT NULL, description text NOT NULL, source_type text, source_id uuid, status text NOT NULL DEFAULT 'draft', created_by uuid REFERENCES asuransi.users(id), approved_by uuid REFERENCES asuransi.users(id), posted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,journal_no));
CREATE TABLE IF NOT EXISTS asuransi.journal_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), journal_entry_id uuid NOT NULL REFERENCES asuransi.journal_entries(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES asuransi.chart_accounts(id), memo text, debit numeric(18,2) NOT NULL DEFAULT 0 CHECK(debit>=0), credit numeric(18,2) NOT NULL DEFAULT 0 CHECK(credit>=0), CHECK(NOT(debit>0 AND credit>0)));
CREATE TABLE IF NOT EXISTS asuransi.tax_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), tax_type text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, due_date date, status text NOT NULL DEFAULT 'open', amount_due numeric(18,2) NOT NULL DEFAULT 0, filing_reference text, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,tax_type,period_start,period_end));
CREATE TABLE IF NOT EXISTS asuransi.knowledge_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_key text UNIQUE NOT NULL, title text NOT NULL, publisher text NOT NULL, source_url text NOT NULL, jurisdiction text NOT NULL DEFAULT 'ID', source_type text NOT NULL, published_at date, checked_at timestamptz, version_label text, content_sha256 text, status text NOT NULL DEFAULT 'queued', license_notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asuransi.knowledge_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES asuransi.knowledge_sources(id), document_title text NOT NULL, section_ref text, language char(2) NOT NULL DEFAULT 'id', content_text text NOT NULL, summary text, effective_from date, effective_to date, verified boolean NOT NULL DEFAULT false, reviewed_by uuid REFERENCES asuransi.users(id), reviewed_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asuransi.ai_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), user_id uuid REFERENCES asuransi.users(id), channel text NOT NULL DEFAULT 'admin', mode text NOT NULL DEFAULT 'offline-first', context_ref jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asuransi.ai_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES asuransi.ai_sessions(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('user','assistant','agent','system')), agent_name text, content text NOT NULL, citations jsonb NOT NULL DEFAULT '[]'::jsonb, safety_flags jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asuransi.ai_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), created_by uuid REFERENCES asuransi.users(id), task_type text NOT NULL, input jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'queued', result jsonb, requires_human_approval boolean NOT NULL DEFAULT true, approved_by uuid REFERENCES asuransi.users(id), approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asuransi.system_settings (tenant_id uuid NOT NULL REFERENCES asuransi.tenants(id), setting_key text NOT NULL, setting_value jsonb NOT NULL DEFAULT '{}'::jsonb, updated_by uuid REFERENCES asuransi.users(id), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,setting_key));
CREATE INDEX IF NOT EXISTS idx_clients_tenant_name ON asuransi.clients(tenant_id,full_name);
CREATE INDEX IF NOT EXISTS idx_policies_tenant_status ON asuransi.policies(tenant_id,status);
CREATE INDEX IF NOT EXISTS idx_claims_tenant_status ON asuransi.claims(tenant_id,status);
CREATE INDEX IF NOT EXISTS idx_audit_tenant_created ON asuransi.audit_logs(tenant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_knowledge_documents_source ON asuransi.knowledge_documents(source_id,verified);
CREATE INDEX IF NOT EXISTS idx_ai_tasks_tenant_status ON asuransi.ai_tasks(tenant_id,status);
